import{_ as a,o as e,c as s,a2 as d}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"职业规划系统","description":"","frontmatter":{},"headers":[],"relativePath":"guide/class-plan.md","filePath":"guide/class-plan.md","lastUpdated":1790873127000}'),l={name:"guide/class-plan.md"};function o(n,t,r,i,c,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="职业规划系统" tabindex="-1">职业规划系统 <a class="header-anchor" href="#职业规划系统" aria-label="Permalink to &quot;职业规划系统&quot;">​</a></h1><p>FunGame 提供 DND 式的<strong>职业规划系统</strong>：玩家消耗<strong>职业点数</strong>选择<strong>职业（Class）与流派（SubClass）</strong>、升级、消耗选择权学习职业技能、分配核心属性、学习与激活<strong>战斗天赋</strong>，从而决定角色的<strong>定位（RoleType）</strong>。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>职业点数（角色升级获得，见 ClassPointsGetterList）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>ClassPlanner（规划器，校验 + 写入 Character.Class + 事件推送）</span></span>
<span class="line"><span>    ├── 选择职业/流派（SelectClass）→ 结算 1 级奖励</span></span>
<span class="line"><span>    ├── 职业升级（UpgradeClass）→ 结算区间奖励</span></span>
<span class="line"><span>    ├── 学习职业技能（LearnClassSkill，消耗选择权）</span></span>
<span class="line"><span>    ├── 初始属性分配 / 数值提升（消耗分配权/提升次数）</span></span>
<span class="line"><span>    ├── 学习/激活战斗天赋（LearnCombatTalent / ActivateCombatTalent）</span></span>
<span class="line"><span>    └── 洗点（ResetPlan）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>ClassRewardLedger（每个职业一本账本：已结算水位、剩余选择权、已施加属性）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>IClassRewardSettler（结算器，可替换扩展点；默认 DefaultClassRewardSettler）</span></span></code></pre></div><ul><li><strong>定义 vs 记录</strong>：<code>Class</code>/<code>SubClass</code> 既是模板也是玩家记录。<code>Class.Copy()</code> 深拷贝技能实例生成&quot;职业记录&quot;，存于 <code>CharacterClass.Classes</code></li><li><strong>升级路线图</strong>：<code>ClassLevelUpReward</code> 描述职业每一级（1–10）发放什么，可整体替换 <code>EquilibriumConstant.ClassLevelUpRewards</code></li><li><strong>奖励账本</strong>：<code>ClassRewardLedger</code> 记录已结算水位 <code>SettledToLevel</code>、已确认下限 <code>CommittedLevel</code>、剩余选择权、已学技能、已施加属性</li><li><strong>结算器</strong>：<code>IClassRewardSettler</code> 是核心扩展点，默认实现 <code>DefaultClassRewardSettler</code>；属性落地经 <code>IClassAttributeApplier</code> 可替换（默认写到 <code>InitialSTR/AGI/INT</code> 与成长）</li></ul><h2 id="升级路线图-默认表" tabindex="-1">升级路线图（默认表） <a class="header-anchor" href="#升级路线图-默认表" aria-label="Permalink to &quot;升级路线图（默认表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职业等级</th><th>奖励</th></tr></thead><tbody><tr><td>1</td><td>流派固有被动 ×1 + 初始属性分配权（30 点属性 + 3.0 成长，受限）</td></tr><tr><td>2</td><td>技能选择权 ×2</td></tr><tr><td>3</td><td>技能提级 ×1 + 魔法额外 +1</td></tr><tr><td>4</td><td>被动 ×1（可用数值提升替代：9 点 + 0.9 成长）</td></tr><tr><td>5</td><td>选择权 ×2 + 提级 ×1 + 魔法额外 +1</td></tr><tr><td>6</td><td>流派固有被动 ×1</td></tr><tr><td>7</td><td>提级 ×1 + 魔法额外 +1</td></tr><tr><td>8</td><td>选择权 ×2 + 提级 ×1 + 魔法额外 +1</td></tr><tr><td>9</td><td>被动 ×2（可用数值提升替代）</td></tr><tr><td>10</td><td>选择权 ×2 + 提级 ×1 + 魔法额外 +1</td></tr></tbody></table><blockquote><p>被动选择与数值提升是同一档的两种选法，<strong>严格互斥</strong>（消耗数值提升时需同时消耗一份被动选择权）。</p></blockquote><h2 id="定位推导" tabindex="-1">定位推导 <a class="header-anchor" href="#定位推导" aria-label="Permalink to &quot;定位推导&quot;">​</a></h2><p>定位<strong>不再由玩家手动选择</strong>，由 <code>ClassPlanRoleResolver</code> 自动推导：</p><ul><li><strong>主要定位</strong>（<code>PrimaryRoleType</code>）= 当前生效战斗天赋所属定位；未激活为 <code>RoleType.None</code></li><li><strong>次要定位</strong>（<code>SecondaryRoleTypes</code>）= 流派按&quot;所属职业等级降序、同级按选择顺序&quot;展开候选，至多 2 个</li><li>主要定位决定 <code>MOV</code>（移动距离）等按定位取值的属性，转换天赋时随之变化</li></ul><h2 id="战斗天赋与转换战技" tabindex="-1">战斗天赋与转换战技 <a class="header-anchor" href="#战斗天赋与转换战技" aria-label="Permalink to &quot;战斗天赋与转换战技&quot;">​</a></h2><ul><li>每个定位的战斗天赋属于被动战技，可学习多个（上限 <code>CharacterClass.MaxLearnedTalentCount</code> = 3），但同一时间只能<strong>激活</strong> 1 个</li><li>学满 2 个天赋后获得【转换战斗天赋】战技（预制实体 <code>SwitchCombatTalentSkill</code>），战斗内可切换生效天赋</li><li>核心定位天赋激活时，普攻与全部主动技能获得 <code>ExLevel + 1</code>（排除 <code>SkillSource.Item/MagicCardPack/Reward</code>）</li></ul><h2 id="存档" tabindex="-1">存档 <a class="header-anchor" href="#存档" aria-label="Permalink to &quot;存档&quot;">​</a></h2><p><code>ClassPlanSnapshot</code> 只保存 IdName 与状态，读档时经 <code>ClassDefinitionRegistry</code>（模组启动时注册职业/流派/转换战技工厂）重建完整定义副本。</p><h2 id="平衡常数" tabindex="-1">平衡常数 <a class="header-anchor" href="#平衡常数" aria-label="Permalink to &quot;平衡常数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>MaxClassLevel</code></td><td>10</td><td>职业等级上限</td></tr><tr><td><code>MaxClassCount</code></td><td>0（不限）</td><td>兼职最多职业数</td></tr><tr><td><code>MinCharacterLevelForMulticlass</code></td><td>1</td><td>兼职所需最低角色等级</td></tr><tr><td><code>MinLevelCanModifyDefaultClass</code></td><td>20</td><td>修改默认职业/洗点完全重选的最低角色等级</td></tr><tr><td><code>InitialAllocationOnlyForFirstClass</code></td><td>true</td><td>仅首个职业发放 1 级初始分配权</td></tr><tr><td><code>ClassPointsGetterList</code></td><td><code>[1,5,10,...,55]</code></td><td>角色升级获得职业点数的等级表</td></tr><tr><td><code>ClassLevelUpRewards</code></td><td>默认路线图</td><td>职业 1–10 级升级奖励</td></tr><tr><td><code>InitialAttributeBudget</code></td><td>30 点 + 3.0 成长（受限）</td><td>1 级初始分配额度</td></tr><tr><td><code>NumericBoostBudget</code></td><td>9 点 + 0.9 成长（不限）</td><td>数值提升单次额度</td></tr></tbody></table><h2 id="相关-api" tabindex="-1">相关 API <a class="header-anchor" href="#相关-api" aria-label="Permalink to &quot;相关 API&quot;">​</a></h2><ul><li>规划器与全部动作 → <a href="/api/ClassPlanner.html">ClassPlanner</a></li><li>转换战斗天赋战技 → <a href="/api/SwitchCombatTalentSkill.html">SwitchCombatTalentSkill</a></li><li>角色定位属性 → <a href="/api/Character.html">Character</a></li></ul>`,19)])])}const C=a(l,[["render",o]]);export{u as __pageData,C as default};
